import os
import zipfile
import glob
from contextlib import contextmanager
import logging
import shutil
from .sshtools import SSHTools, run_command

try:
    from robotide.lib.robot.api import logger
except ImportError:
    from robot.api import logger


def find_newest_file_in_directory(directory, pattern):
    """

    Find file with exact pattern in given directory

    """
    logger.debug('Searching for newest file matching pattern "{}" in {}'.format(pattern, directory))
    packages = glob.glob(os.path.join(directory, pattern))
    if packages:
        newest = max(packages, key=os.path.getmtime)
        logger.info("Found {} file(s), using the newest one: {}".format(len(packages), newest), also_console=True)
        return newest
    raise LookupError('No files matching pattern "{}" found in {}'.format(pattern, directory))


def extract_package(directory, package):
    """

    Extract package @package in @directory

    """
    logger.debug("Extracting package {}".format(package))
    with zipfile.ZipFile(package) as archive:
        exctracted_archive_directory = os.path.join(directory, os.path.splitext(package)[0])
        archive.extractall(exctracted_archive_directory)
        logger.debug("Extracted {} to {}".format(package, exctracted_archive_directory))
        return exctracted_archive_directory


@contextmanager
def _chdir(path):
    old = os.getcwd()
    os.chdir(path)
    try:
        yield
    finally:
        os.chdir(old)


class Yaft(object):
    def __init__(
            self,
            software_pattern,
            ssh_user,
            ssh_password,
            packages_directory="/home/ute/btsauto/TARGET_SW",
            swconfig_path=None,
            msm_ip="192.168.255.129",
            log_directory="/home/ute/Autotest",
            optional_sign_directory=None,
            ignore_fsps=False,
    ):
        self.msm_ip = msm_ip
        self.packages_directory = packages_directory
        self.software_patern = software_pattern
        self.swconfig_path = swconfig_path
        self.yaft_log_directory = log_directory
        self.directory = None
        self.optional_sign_directory = optional_sign_directory
        self.ssh = SSHTools(ssh_user, ssh_password, self.msm_ip)
        self.ignore_fsps = ignore_fsps

    def install_software_from_directory_using_yaft(self):
        if os.path.isdir(self.packages_directory):
            self.ssh.add_ssh_public_key()
            logger.debug("Installing {} from {}".format(self.software_patern, self.packages_directory))
            package = find_newest_file_in_directory(self.packages_directory, "*{}*.zip".format(self.software_patern))
            self.directory = extract_package(self.packages_directory, package)
            self.update_yaft_in_directory(self.directory)
            self.change_or_remove_swconfig_in_yaft(self.directory, self.swconfig_path)
            status = self.run_yaft_command(self.directory, self.msm_ip, self.yaft_log_directory, self.ignore_fsps)
            if not status:
                return status
            if self.optional_sign_directory:
                self.ssh.sign_files_in_dedicated_directories(self.optional_sign_directory)
            self.ssh.reboot_and_wait_for_reset()
            return status
        else:
            raise EnvironmentError('"{}" is not a directory'.format(self.packages_directory))

    @staticmethod
    def update_yaft_in_directory(package_directory):
        """

        Copy yaft installed with workspace in /opt/yaft to @package_directory

        """
        yaft_source = "/opt/yaft/"
        yaft_dest = os.path.join(package_directory, "YAFT")
        logger.debug("Placing YAFT from {} at {}".format(yaft_source, yaft_dest))
        if os.path.exists(yaft_dest):
            shutil.rmtree(yaft_dest)
        shutil.copytree(yaft_source, yaft_dest)

    @staticmethod
    def change_or_remove_swconfig_in_yaft(directory, swconfig_path=None):
        if swconfig_path:
            try:
                shutil.copyfile(swconfig_path, "{}/YAFT/libyaft/swconfig.txt".format(directory))
                logger.info("User swconfig has been added to YAFT", also_console=True)
            except IOError:
                logger.warn("Custom swconfig was not found.")
                with open(os.path.join(directory, "YAFT/libyaft/swconfig.txt"), "w"):
                    pass
        else:
            open(os.path.join(directory, "YAFT/libyaft/swconfig.txt"), "w").close()
            logger.debug("Default YAFT swconfig deleted from: {}/YAFT/libyaft/swconfig.txt".format(directory))

    def run_yaft_command(self, directory, msm_ip, log_directory, ignore_FSPs=False):
        sw_dir = "bts_sw" if os.path.exists(os.path.join(directory, "bts_sw")) else "BTS_SW"
        if ignore_FSPs:
            command = "python YAFT/yaft.py -R -i {} -d {} -l {} -C --ignore_FSPs --clean_to_default"\
                .format(msm_ip, sw_dir, log_directory)
        else:
            command = "python YAFT/yaft.py -R -i {} -d {} -l {} -C --clean_to_default"\
                .format(msm_ip, sw_dir, log_directory)
        msg = "Running command ({}) from software package directory {}".format(command, directory)
        logger.info(msg, also_console=True)
        with _chdir(directory):
            returncode = run_command(command, also_console=True)
            if returncode == 0:
                logger.info("Update script succeeded with return code 0", also_console=True)
                return True
            else:
                logging.critical("Update script failed with return code {}".format(returncode))
                return False
